import React, { useEffect, useState } from 'react';
import api from '../../services/api';

const BASE_URL = 'http://localhost:8081';

// Image fields come back as relative paths (e.g. "uploads/xyz.jpg"), not full URLs.
const resolveImageUrl = (path) => {
  if (!path) return null;
  if (/^https?:\/\//i.test(path)) return path; // already absolute
  return `${BASE_URL}/${String(path).replace(/^\/+/, '')}`;
};

const cellStyle = { border: '1px solid #000', padding: '3px 5px', fontSize: '0.8rem', lineHeight: 1.2 };
const labelStyle = { ...cellStyle, fontWeight: 600, background: '#f4f4f4' };

const Row = ({ label, value }) => (
  <tr>
    <td style={{ ...labelStyle, width: '38%' }}>{label}</td>
    <td style={cellStyle}>{value ?? ''}</td>
  </tr>
);

const QuadRow = ({ l1, v1, l2, v2 }) => (
  <tr>
    <td style={{ ...labelStyle, width: '25%' }}>{l1}</td>
    <td style={{ ...cellStyle, width: '25%' }}>{v1 ?? ''}</td>
    <td style={{ ...labelStyle, width: '25%' }}>{l2}</td>
    <td style={{ ...cellStyle, width: '25%' }}>{v2 ?? ''}</td>
  </tr>
);

/**
 * Print-only preview modal for a single completed order.
 * Renders the attached print format and prints only that content.
 * IMPORTANT: add the CSS block below to a global stylesheet (index.css / App.css) —
 * it neutralizes the Bootstrap modal's fixed positioning/height cap so the
 * whole document prints (not just the on-screen viewport slice), and hides
 * everything outside #order-print-area.
 *
 *   @media print {
 *     body * { visibility: hidden; }
 *     #order-print-area, #order-print-area * { visibility: visible; }
 *
 *     .modal, .modal-dialog, .modal-content, .modal-body {
 *       position: static !important;
 *       overflow: visible !important;
 *       height: auto !important;
 *       max-height: none !important;
 *       width: 100% !important;
 *       margin: 0 !important;
 *       padding: 0 !important;
 *       box-shadow: none !important;
 *       border: none !important;
 *     }
 *
 *     #order-print-area {
 *       position: absolute;
 *       left: 0;
 *       top: 0;
 *       width: 100%;
 *     }
 *
 *     table, tr { page-break-inside: avoid; }
 *     .no-print { display: none !important; }
 *   }
 */

// .NET's default JSON serializer lowercases the first letter of each property
// name (Order_Number -> order_Number, CAD_Image_URL -> cAD_Image_URL, etc.).
// This wraps the response so field access below works regardless of whether
// the API returns PascalCase or camelCase keys.
const normalize = (obj) => {
  if (!obj || typeof obj !== 'object') return obj;
  const lowerMap = {};
  Object.keys(obj).forEach(k => { lowerMap[k.toLowerCase()] = obj[k]; });
  return new Proxy(obj, {
    get(target, prop) {
      if (typeof prop !== 'string') return target[prop];
      if (prop in target) return target[prop];
      return lowerMap[prop.toLowerCase()];
    }
  });
};

const OrderPrintModal = ({ orderId, onClose }) => {
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!orderId) { setOrder(null); return; }
    setLoading(true);
    api.get(`${BASE_URL}/api/order/GetOrderPrint?orderID=${orderId}`)
      .then(r => {
        const raw = Array.isArray(r.data) ? r.data[0] : r.data;
        setOrder(normalize(raw));
      })
      .catch(() => setOrder(null))
      .finally(() => setLoading(false));
  }, [orderId]);

  if (!orderId) return null;

  return (
    <div className="modal show d-block" tabIndex={-1} style={{ background: 'rgba(0,0,0,0.5)' }}>
      <div className="modal-dialog modal-lg modal-dialog-centered">
        <div className="modal-content">
          <div className="modal-header no-print">
            <h5 className="modal-title">Order Print Preview</h5>
            <button type="button" className="btn-close" onClick={onClose}></button>
          </div>

          <div className="modal-body" style={{ padding: '0.75rem 1rem' }}>
            {loading ? (
              <div className="text-center py-5"><span className="spinner-border text-primary" /></div>
            ) : !order ? (
              <div className="text-center py-5 text-muted">Unable to load order.</div>
            ) : (
              <div id="order-print-area">
                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                  <tbody>
                    <tr>
                      <td style={{ verticalAlign: 'top', width: '45%' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                          <tbody>
                            <Row label="Order Number" value={order.Order_Number} />
                            <Row label="Customer Name" value={order.Customer_Name} />
                            <Row label="Order Date" value={order.Order_DT} />
                            <Row label="Design" value={order.Design} />
                            <Row label="Quantity" value={order.Quantity} />
                            <Row label="Karat" value={order.Karat} />
                            <Row label="Design Type" value={order.Design_Type} />
                            <Row label="Gold Colour" value={order.Gold_Colour} />
                            <Row label="Size" value={order.Size} />
                            <Row label="Stone Name" value={order.Stone_Name} />
                            <Row label="Diamond Quality" value={order.Diamond_Quality} />
                            <Row label="Certificate Name" value={order.Cretificate_Name} />
                            <Row label="Colour Stone Name" value={order.Colour_Stone_Name} />
                            <Row label="Completed Date" value={order.Order_Complete_DT} />
                          </tbody>
                        </table>
                      </td>
                      <td style={{ verticalAlign: 'top', width: '55%', paddingLeft: 8 }}>
                        {(() => {
                          const imgSrc = resolveImageUrl(order.CAD_Image_URL) || resolveImageUrl(order.Front_Image_URL);
                          return imgSrc ? (
                            <img
                              src={imgSrc}
                              alt="Design"
                              style={{ width: '100%', maxHeight: 200, objectFit: 'contain', border: '1px solid #ccc' }}
                            />
                          ) : (
                            <div className="text-muted text-center border py-3">No design image</div>
                          );
                        })()}
                      </td>
                    </tr>
                  </tbody>
                </table>

                <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 8 }}>
                  <tbody>
                    <QuadRow l1="Gross Weight" v1={order.Final_Gross_Weight} l2="No. of Diamonds" v2={order.Final_Noof_Diamonds} />
                    <QuadRow l1="Diamond Weight" v1={order.Final_Diamond_Weight} l2="Diamond Value" v2={order.Diamond_Value} />
                    <QuadRow l1="No. Of Colour Stone" v1={order.NoOfColour_Stone} l2="Colour Stone Weight" v2={order.ColourStone_Weight} />
                    <QuadRow l1="Colour Stone Value" v1={order.ColourStone_Value} l2="OTH No. Of Colour Stone" v2={order.Others_NoOfColour_Stone} />
                    <QuadRow l1="OTH CLR Stone WT" v1={order.Others_Colour_Stone_Weight} l2="OTH CLR Stone Value" v2={order.Other_Colour_Stone_Value} />
                    <QuadRow l1="Final Net Weight" v1={order.Final_Net_Weight} l2="Final Net Weight (24kt)" v2={order.Final_Net_Weight_24kt} />
                    <QuadRow l1="Gold Loss" v1={order.Gold_Loss} l2="Labour Charge" v2={order.Labour_Charge} />
                    <QuadRow l1="Gold Loss (24kt)" v1={order.Gold_Loss_24kt} l2="Certificate Charge" v2={order.Certificate_Charge} />
                    <Row label="Other Charges" value={order.Other_Charges} />
                    <QuadRow l1="Bill Amount" v1={order.Bill_Amount} l2="Final Gold Weight (24kt)" v2={order.Final_Gold_Weight_24kt} />
                  </tbody>
                </table>
              </div>
            )}
          </div>

          <div className="modal-footer no-print">
            <button type="button" className="btn btn-secondary" onClick={onClose}>Close</button>
            <button
              type="button"
              className="btn btn-primary"
              disabled={loading || !order}
              onClick={() => window.print()}
            >
              <i className="bi bi-printer me-1"></i>Print
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default OrderPrintModal;
